  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Seit ein paar Tagen müde','چند روز خستگی','Sara bemerkt Mias Müdigkeit und fragt nach Schlaf und Erholung.','سارا متوجه خستگی میا می‌شود و دربارهٔ خواب و استراحت او می‌پرسد.','story','mia-sara-b1-health-routine',1,53,180,1,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"notice-tiredness"}'); SET v_l_1=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_sara,1,'character','Du siehst heute ziemlich müde aus.','امروز خیلی خسته به نظر می‌رسی.',53,NULL,NULL,NULL,NULL,'[{"surface":"Du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"siehst","lemma":"aussehen","translation":"به نظر رسیدن","partOfSpeech":"verb"},{"surface":"heute","lemma":"heute","translation":"امروز","partOfSpeech":"adverb"},{"surface":"ziemlich","lemma":"ziemlich","translation":"نسبتا / خیلی","partOfSpeech":"adverb"},{"surface":"müde","lemma":"müde","translation":"خسته","partOfSpeech":"adjective"},{"surface":"aus","lemma":"aussehen","translation":"به نظر رسیدن","partOfSpeech":"verb","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_1=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_mia,2,'learner','Ich fühle mich seit ein paar Tagen müde.','چند روز است که احساس خستگی می‌کنم.',53,NULL,NULL,'ich fühle mich seit ein paar tagen müde',NULL,'[{"surface":"Ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"fühle","lemma":"sich fühlen","translation":"احساس کردن","partOfSpeech":"verb"},{"surface":"mich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"seit","lemma":"seit","translation":"از / از زمان","partOfSpeech":"preposition"},{"surface":"ein","lemma":"ein","translation":"یک / حرف تعریف نامعین","partOfSpeech":"article"},{"surface":"paar","lemma":"paar","translation":"چند","partOfSpeech":"determiner"},{"surface":"Tagen","lemma":"Tag","translation":"روز","partOfSpeech":"noun"},{"surface":"müde","lemma":"müde","translation":"خسته","partOfSpeech":"adjective","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_2=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_sara,3,'character','Hast du in letzter Zeit genug geschlafen?','این اواخر به اندازهٔ کافی خوابیده‌ای؟',53,NULL,NULL,NULL,NULL,'[{"surface":"Hast","lemma":"haben","translation":"داشتن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"in","lemma":"in","translation":"در / داخل","partOfSpeech":"preposition"},{"surface":"letzter","lemma":"letzt","translation":"آخرین","partOfSpeech":"adjective"},{"surface":"Zeit","lemma":"Zeit","translation":"وقت / زمان","partOfSpeech":"noun"},{"surface":"genug","lemma":"genug","translation":"کافی","partOfSpeech":"adverb"},{"surface":"geschlafen","lemma":"schlafen","translation":"خوابیدن","partOfSpeech":"verb","suffix":"?"}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_3=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_mia,4,'learner','Nein, ich wache nachts oft auf.','نه، شب‌ها زیاد از خواب بیدار می‌شوم.',53,NULL,NULL,'nein ich wache nachts oft auf',NULL,'[{"surface":"Nein","lemma":"nein","translation":"نه","partOfSpeech":"interjection","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"wache","lemma":"aufwachen","translation":"بیدار شدن","partOfSpeech":"verb"},{"surface":"nachts","lemma":"nachts","translation":"شب‌ها","partOfSpeech":"adverb"},{"surface":"oft","lemma":"oft","translation":"اغلب","partOfSpeech":"adverb"},{"surface":"auf","lemma":"aufwachen","translation":"بیدار شدن","partOfSpeech":"verb","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_4=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_sara,5,'character','Vielleicht brauchst du mehr Ruhe.','شاید به استراحت بیشتری نیاز داری.',53,NULL,NULL,NULL,NULL,'[{"surface":"Vielleicht","lemma":"vielleicht","translation":"شاید","partOfSpeech":"adverb"},{"surface":"brauchst","lemma":"brauchen","translation":"نیاز داشتن / لازم داشتن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"mehr","lemma":"mehr","translation":"دیگه / بیشتر","partOfSpeech":"adverb"},{"surface":"Ruhe","lemma":"Ruhe","translation":"آرامش / سکوت","partOfSpeech":"noun","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_5=LAST_INSERT_ID();
